def minimalBases(classes: list[type]) -> list[type]:
    # Check if the input is valid
    if not isinstance(classes, list):
        raise ValueError("Input must be a list of classes")

    # Create a set to keep track of the unique bases
    unique_bases = set()

    # Iterate over the classes and their bases
    for cls in classes:
        while cls.__bases__:
            # Add the base to the set if it's not already there
            unique_bases.add(cls.__bases__[0])
            # Go up one level in the bases tree
            cls = cls.__bases__[0]

    # Return the list of unique bases in order
    return list(unique_bases)

