public static Object[] normalizeArgs(Object[] sequence, Object output) {
    List<Object> normalizedSequence = new ArrayList<>();

    for (Object arg : sequence) {
        if (arg instanceof Declaration) {
            normalizedSequence.add(((Declaration) arg).getInterface());
        } else if (arg instanceof Tuple) {
            normalizedSequence.add(normalizeTuple((Tuple) arg));
        } else if (arg instanceof Interface) {
            normalizedSequence.add(arg);
        } else {
            throw new IllegalArgumentException("Unsupported argument type for normalization: " + arg.getClass().getName());
        }
    }

    if (output != null) {
        normalizedSequence.add(output);
    }

    return normalizedSequence.toArray();
}

public static Object normalizeTuple(Tuple tuple) {
    List<Object> normalizedTuple = new ArrayList<>();

    for (Object element : tuple.getRealization().getImplementations()) {
        if (element instanceof Declaration) {
            normalizedTuple.add(((Declaration) element).getInterface());
        } else if (element instanceof Tuple) {
            normalizedTuple.add(normalizeTuple((Tuple) element));
        } else if (element instanceof Interface) {
            normalizedTuple.add(element);
        } else {
            throw new IllegalArgumentException("Unsupported element type for normalization: " + element.getClass().getName());
        }
    }

    return normalizedTuple;
}

