def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments

    This method takes a sequence of declaration arguments and outputs a normalized version of those arguments that contain tuples, individual interfaces, or a single implementation spec.

    Args:
        sequence (list | tuple): A sequence of declaration arguments
        output: Optional. The output type to normalize to. If not provided, the output type will be inferred from the input sequence.

    Returns:
        list | tuple: A normalized version of the input sequence.
    """

    if output is not None:
        if not isinstance(output, type):
            raise ValueError("Output must be a type")

    # Normalize individual interfaces or implements specs
    normalized_sequence = []
    for item in sequence:
        if isinstance(item, interfaces.Declaration):
            # If item is an individual interface or implement spec, expand it
            if isinstance(item, interfaces.Process):
                normalized_sequence.append(item.spec)
            else:
                normalized_sequence.append(item)
        elif isinstance(item, tuple):
            # If item is a tuple, expand it
            normalized_sequence.extend(item)
        else:
            # If item is not an individual interface or implement spec, and not a tuple, add it to the normalized sequence as is
            normalized_sequence.append(item)

    # If output is provided, convert the normalized sequence to the provided type
    if output is not None:
        if issubclass(output, tuple):
            return tuple(normalized_sequence)
        else:
            return list(normalized_sequence)
    else:
        # If output is not provided, return the normalized sequence
        return normalized_sequence

def normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if not isinstance(sequence, (list, tuple)):
        raise ValueError("'sequence' must be a list or tuple")

    if output is not None and not isinstance(output, list):
        raise ValueError("'output' must be a list if specified")

    expanded_sequence = []
    for elem in sequence:
        if isinstance(elem, Declaration):
            expanded_sequence.append(elem)
        elif isinstance(elem, Tuple):
            expanded_sequence.append(list(elem))
        elif isinstance(elem, Interface):
            expanded_sequence.append(elem)
        else:
            raise ValueError("Unknown element type in 'sequence': {}".format(elem))

    if output is not None:
        output.extend(expanded_sequence)
        return output
    else:
        return expanded_sequence

