    except KeyError:
        logger.error(f'Object at path {path} does not exist')
        return False
    if not obj.is_dir():
        logger.error(f'Path {path} is not a directory')
        return False
    if not obj.has_attributes(ocfl_keys=True):
        logger.error(f'Object at path {path} does not have OCFL attributes')
        return False
    if not obj.has_children(ocfl_keys=True):
        logger.error(f'Object at path {path} does not have any children')
        return False
    return True

