def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Check that all digests in the manifest are present and used
    # in the list of available digests
    if len(manifest_files) > 0:
        # Create a set of digests used in the manifest
        used_digests = set(manifest_files[0].keys())
        # Iterate over the remaining manifest files
        for manifest_file in manifest_files[1:]:
            # Add the digests for the current manifest file to the set
            used_digests |= set(manifest_file.keys())
        # Check that all the needed digests are present in the set of used digests
        for digest in digests_used:
            if digest not in used_digests:
                raise ValueError(f'Digest {digest} is not present in the manifest')
    # Return a list of digests used in the manifest
    return list(used_digests)

def check_digests_present_and_used(manifest_files, digests_used):
    # Create a set of digests used in the manifest
    used_digests = set(digests_used)

    # Iterate over all files in the manifest and check if all necessary digests are present
    for file in manifest_files:
        # Extract the digests used in the current file from the manifest
        file_digests = set(file.get("digests", []))

        # Check if all necessary digests are present in the file
        if not (used_digests <= file_digests):
            raise ValueError(f"Missing necessary digests in file {file.get('path')}")

        # Check if any extra digests are present in the file
        if file_digests - used_digests:
            raise ValueError(f"Unused digests in file {file.get('path')}")

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    for manifest_file in manifest_files:
        with open(manifest_file, "r") as f:
            manifest_content = f.read()
            for digest in digests_used:
                if digest not in manifest_content:
                    raise ValueError(f"Digest {digest} is not present in manifest file {manifest_file}.")

            for line in manifest_content.splitlines():
                if "digest" in line and any(d in line for d in digests_used):
                    used_digests = line.split('digest')[1].split(' ')[0].split('\n')
                    for used_digest in used_digests:
                        if used_digest not in digests_used:
                            raise ValueError(f"Digest {used_digest} is not in the digests used list.")

    return True

