def get_logical_path_map(inventory, version):
    logical_path_map = {}

    # Iterate over the inventory to find all content files for the given version
    for content_file in inventory.content_files:
        if content_file.version == version:
            # Get the logical path for this file
            logical_path = content_file.logical_path

            # Add this file to the set of files for this logical path
            if logical_path not in logical_path_map:
