import zipfile

def _explore_zipfile(zip_path):
    with zipfile.ZipFile(zip_path, "r") as zf:
        files = zf.infolist()
        file_paths = [f.filename for f in files]
        basenames = [os.path.basename(f) for f in file_paths]
        groups = {b: [f for f in file_paths if os.path.basename(f) == b] for b in basenames}
        data = {}
        for group in groups:
            data[group] = []
            for file in groups[group]:
                with zf.open(file, "r") as f:
                    file_data = f.read()
                data[group].append(file_data)
    return data

def explore_zipfile(zip_path):
