def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    if debug:
        print(f"Pretty: {self}. indent: {indent}")

    # handle the case where self is None
    if self is None:
        return "None"

    # handle the case where self is a string
    if isinstance(self, str):
        return f"\"{self}\""

    # handle the case where self is a number
    if isinstance(self, (int, float)):
        return str(self)

    # handle the case where self is a list
    if isinstance(self, list):
        return "[" + ", ".join(self.pretty(indent + 1, debug) for x in self) + "]"

    # handle the case where self is a tuple
    if isinstance(self, tuple):
        return "(" + ", ".join(self.pretty(indent + 1, debug) for x in self) + ")"

    # handle the case where self is a dictionary
    if isinstance(self, dict):
        return "{" + ", ".join(f"{k}: {v.pretty(indent + 1, debug)}" for k, v in self.items()) + "}"

    # handle the case where self is some other type of object
    return f"<{self.__class__.__name__} object>"

