def absorb(self, args):
    if not args:
        raise ValueError("absorb() expected at least one argument, got 0")

    result = []
    for i, arg in enumerate(args):
        if arg.operator == "|":
            # operating on a union
            for subarg in arg.operands:
                if subarg.operator == "&" and subarg.operands[0].value == arg.value:
                    # absorption
                    result.append(absorb(subarg.operands[1]))
                elif subarg.operator == "&" and subarg.operands[1].value == arg.value:
                    # negative absorption
                    result.append(absorb([subarg.operands[0], arg]))
                else:
                    # not absorption or negative absorption, no change
                    result.append(subarg)
        else:
            # operating on a simple expression
            if arg.operator == "&" and arg.operands[0].value == arg.value:
                # absorption
                result.append(arg.operands[1])
            elif arg.operator == "&" and arg.operands[1].value == arg.value:
                # negative absorption
                result.append(arg.operands[0])
            else:
                # not absorption or negative absorption, no change
                result.append(arg)

    return result

