    new_args = []
    for arg in args:
        if isinstance(arg, tuple):
            if len(arg) > 2:
                raise ValueError("Invalid argument length")
            operator, operand = arg[0], arg[1]
            if operator == '&':
                new_args.append((operator, operand))
            elif operator == '|':
                if operand == '~':
                    raise ValueError("Negative absorption is not supported")
                new_args.append(arg)
            else:
                raise ValueError("Invalid operator")
        else:
            new_args.append((operator, operand))
    return new_args

