def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Calls the given command(s).

    :param commands: the command(s) to run (list of string)
    :param args: the arguments to pass to the command(s) (list of string)
    :param cwd: the current working directory (default=None)
    :param verbose: if True, show output of command(s) (default=False)
    :param hide_stderr: if True, hide error messages (default=False)
    :param env: the environment variables to pass to the command(s) (default=None)

    :raises TypeError: if any arguments have the wrong type
    :raises ValueError: if any arguments have an invalid value
    :raises RuntimeError: if the command(s) failed to run

    :return: the output of the command(s)
    """

    if not isinstance(commands, list):
        raise TypeError("'commands' should be a list of command(s)")

    if not isinstance(args, list):
        raise TypeError("'args' should be a list of argument(s)")

    if cwd is not None and not isinstance(cwd, str):
        raise TypeError("'cwd' should be a string")

    if env is not None and not isinstance(env, dict):
        raise TypeError("'env' should be a dictionary of environment variable(s)")

    if hide_stderr and verbose:
        raise ValueError("'hide_stderr' and 'verbose' cannot be True at the same time")

    try:
        process = subprocess.Popen(commands, args, cwd=cwd, env=env)
        output, error = process.communicate()

        if verbose:
            print(output.decode())

        if hide_stderr:
            error = None

        if error:
            raise RuntimeError("Command(s) failed to run")

        return output

    except subprocess.CalledProcessError as e:
        print("Command(s) failed with error code", e

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    import subprocess
    import sys

    if verbose:
        print(f"Running command(s): {commands}")
    try:
        process = subprocess.Popen(commands, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.STDOUT if hide_stderr else subprocess.PIPE)
        output, error = process.communicate(input=args)
        retcode = process.poll()
        if retcode:
            raise subprocess.CalledProcessError(retcode, process.args, output=output, stderr=error)
        if verbose:
            print(f"Command(s) exited with code {retcode}")
        return output
    except Exception as e:
        if verbose:
            print(f"Command(s) failed with error: {e}")
        raise

