    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """

    try:
        namaste_file = open(os.path.join(path, "0=*"), "r")
        contents = namaste_file.read()
        namaste_file.close()

        if " represents an OCFLStorageRoot" in contents:
            return "root"
        if " represents an OCFLObject" in contents:
            return "object"
        if " represents an OCFLFile" in contents:
            return "file"
        else:
            return "unable to determine directory type"

    except FileNotFoundError:
        return "could not find 0=* file"

def find_path_type(path):
    # Check if the path is a valid directory
    if not os.path.isdir(path):
        raise ValueError(f"{path} is not a valid directory")

    # Check if the path contains "0=*" Namaste files to determine the directory type
    namaste_files = [f for f in os.listdir(path) if f.startswith("0=*")]
    if len(namaste_files) == 0:
        raise ValueError(f"{path} does not contain any \"0=*\" Namaste files")

    # Determine the directory type based on the Namaste files
    first_file = namaste_files[0]
    if first_file.startswith("0=StorageRoot"):
        return "root"
    elif first_file.startswith("0=Object"):
        return "object"
    elif first_file.startswith("0=File"):
        return "file"
    else:
        raise ValueError(f"Could not determine the directory type of {path}")

