    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """

    # dict to store parsed arguments for each subparser
    subparser_arguments = {}

    # list to store remaining unclaimed arguments
    remaining_arguments = []

    # loop through each argument
    for arg in unparsed_arguments:
        # check if the argument is a subparser name
        if arg in subparsers:
            # if so, try to parse its arguments using the subparser object
            try:
                subparser_arguments[arg] = subparsers[arg].parse_args(unparsed_arguments)
            except SystemExit:
                # if parsing fails, add the argument back to the list of remaining unclaimed arguments
                remaining_arguments.append(arg)
        else:
            # if the argument is not a subparser name, add it to the list of remaining unclaimed arguments
            remaining_arguments.append(arg)

    # return the parsed arguments and remaining unclaimed arguments
    return subparser_arguments, remaining_arguments

