def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser instance,
    give each requested action's subparser a shot at parsing all arguments. This allows common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of arguments, a list of remaining arguments not claimed by any subparser).
    """
    unparsed_arguments = list(unparsed_arguments)
    parser_names = [name for parser in subparsers.values() for name in parser.prefix_chars]
    parsed_arguments = {}
    remaining_arguments = []

    while unparsed_arguments:
        arg = unparsed_arguments.pop(0)
        parser = None
        if arg.startswith("-"):
            if len(arg) > 1:
                for prefix in parser_names:
                    if arg.startswith(prefix):
                        parser = subparsers[prefix]
                        break
            else:
                parser = subparsers[arg]
        if parser is not None:
            try:
                namespace = parser.parse_args(unparsed_arguments)
                parsed_arguments[parser.prog] = namespace
                break
            except SystemExit:
                remaining_arguments.extend([arg] + unparsed_arguments)
                break
        else:
            remaining_arguments.append(arg)

    return parsed_arguments, remaining_arguments

def parse_subparser_arguments(unparsed_arguments, subparsers):
    # Initialize an empty dictionary to store the parsed arguments for each subparser
    parsed_args_dict = {}

    # Iterate over the unparsed arguments
    for arg in unparsed_arguments:
        # Check if the argument is a flag or option
        if arg.startswith("-"):
            # If it is, attempt to parse it with each subparser
            for parser_name, parser in subparsers.items():
                try:
                    # Try to parse the argument with the current subparser
                    parser.parse_args(arg)
                    # If parsing was successful, store the parsed argument in the parsed arguments dictionary
                    parsed_args_dict[parser_name] = parser.parse_args(arg)
                    # And stop attempting to parse this argument with other subparsers
                    break
                except SystemExit:
                    # If parsing failed, continue attempting to parse the argument with other subparsers
                    pass
        else:
            # If the argument is not a flag or option, attempt to parse it with each subparser
            for parser_name, parser in subparsers.items():
                try:
                    # Try to parse the argument with the current subparser
                    parser.parse_args(arg)
                    # If parsing was successful, store the parsed argument in the parsed arguments dictionary
                    parsed_args_dict[parser_name] = parser.parse_args(arg)
                    # And stop attempting to parse this argument with other subparsers
                    break
                except SystemExit:
                    # If parsing failed, continue attempting to parse the argument with other subparsers
                    pass

    # Return the parsed arguments dict and the remaining arguments not claimed by any subparser
    return parsed_args_dict, [arg for arg in unparsed_arguments if arg not in parsed_args_dict]

