def size_to_bytes(size: str) -> int:
    '''
    Convert human-readable file size to bytes.

    This method will return a round value. If you need an exact number, use the
    `filesize` module.
    '''

    if not isinstance(size, str):
        raise TypeError("size must be a string")

    size = size.lower()

    if size.endswith("kb"):
        return int(size[:-2]) * 1000
    elif size.endswith("mb"):
        return int(size[:-2]) * 1000 * 1000
    elif size.endswith("gb"):
        return int(size[:-2]) * 1000 * 1000 * 1000
    elif size.endswith("tb"):
        return int(size[:-2]) * 1000 * 1000 * 1000 * 1000
    else:
        raise ValueError("{size} is not a valid size")

def size_to_bytes(size: str) -> int:
    """
    Convert human readable file size to bytes.
    :param size: A string representing a human readable file size (eg: '500K')
    :return: A decimal representation of file size
    """
    kilobyte = 1024
    megabyte = 1024 ** 2
    gigabyte = 1024 ** 3
    terabyte = 1024 ** 4

    try:
        size = size.upper()
        if "K" in size:
            return int(size.replace("K", "")) * kilobyte
        elif "M" in size:
            return int(size.replace("M", "")) * megabyte
        elif "G" in size:
            return int(size.replace("G", "")) * gigabyte
        elif "T" in size:
            return int(size.replace("T", "")) * terabyte
        else:
            raise ValueError("Invalid input string")
    except ValueError as err:
        raise ValueError("Bad size representation: " + size) from err

