def get_repo_archive(url: str, destination_path: Path) -> Path:
    try:
        with requests.get(url, stream=True) as response:
            with open(destination_path / "temp.tar.gz", "wb") as file:
                for chunk in response.iter_content(chunk_size=1024):
                    file.write(chunk)

        with tarfile.open(destination_path / "temp.tar.gz", "r:gz") as tar:
            tar.extractall(path=destination_path)

        (destination_path / "desc").rename(destination_path / "repo_desc.json")
        return destination_path
    except requests.exceptions.RequestException as e:
        raise Exception(f"Failed to retrieve repository archive: {e}")
    except tarfile.TarError as e:
        raise Exception(f"Failed to extract repository archive: {e}")
    except OSError as e:
        raise Exception(f"Failed to rename repository archive: {e}")
    else:
        return destination_path

