def get_ignored_files_as_string(ignored):
    """
    Use the `git ls-files -others` command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.

    Args:
        ignored (bool): flag indicating whether to return ignored files or not

    Returns:
        str: string containing the list of ignored files
    """
    command = "git ls-files -others"
    if ignored:
        command += " --ignored"
    try:
        output = subprocess.check_output(command, shell=True)
        files = output.decode("utf-8").strip().split("\n")
        for file in files:
            if file.startswith("!"):
                files.remove(file)
    except subprocess.CalledProcessError:
        files = []
    return ", ".join(files)

