        try:
            with open(config_filename, "r") as config_file:
                config = yaml.safe_load(config_file)
            if not isinstance(config, dict):
                raise ValueError(f"Configuration file {config_filename} is not a valid YAML dictionary")
        except (IOError, ValueError) as e:
            errors.append(logging.LogRecord(level=logging.ERROR, message=f"Configuration file load error - {e}", fn=config_filename))
            continue

        # Step 2: Override the configurations with any specified overrides
        if overrides:
            for key, value in overrides.items():
                if key not in config:
                    errors.append(logging.LogRecord(level=logging.ERROR, message=f"Override key {key} not found in configuration file {config_filename}", fn=config_filename))
                    continue
                config[key] = value

        # Step 3: Resolve environment variables and load the parsed configuration into a dict
        if resolve_env:
            config = resolve_env_vars(config)
            logging.debug(f"Resolved environment variables in configuration file {config_filename}")

        # Step 4: Store the loaded configuration and any load errors
        configs[config_filename] = config
        if errors:
            errors.append(logging.LogRecord(level=logging.ERROR, message=f"Configuration file load errors in {config_filename}", fn=config_filename))

    # Step 5: Return the loaded configurations and any load errors
    return configs

