    if ticks < 0 or ticks >= 86400000000000:
        raise ValueError("ticks is out of bounds")
    hours, minutes, seconds = ticks // 3600, (ticks % 3600) // 60, (ticks % 60)
    microseconds = (ticks % 1) * 1000000
    if tz is None:
        return cls(hours, minutes, seconds, microseconds)
    else:
        return cls(hours, minutes, seconds, microseconds, tz)

