def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair. Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    # Handle edge case for when the input is a string or a number
    if isinstance(seq, str):
        return seq, str
    elif isinstance(seq, numbers.Number):
        return seq, float

    # If the input is a sequence, determine the type of the elements
    if isinstance(seq, collections.abc.Sequence):
        # Determine the type of the first element
        first_element_type = type(seq[0])

        # Check if all elements are of the same type
        all_element_types = [type(element) for element in seq]
        if all_element_types.count(first_element_type) == len(seq):
            return seq, first_element_type
        else:
            raise ValueError("Sequence contains elements of different types.")

    # Handle other types of input
    else:
        return seq, type(seq)

