def _verify(iface, candidate, tentative=False, vtype=None):
    if not tentative:
        # Make sure the candidate claims that it provides the interface
        if not iface.providedBy(candidate):
            raise zope.interface.Invalid("{} does not provide {}".format(candidate, iface))

    # Make sure the candidate defines all the necessary methods
    for method in iface.getProvidedMethods():
        if not hasattr(candidate, method.name):
            raise zope.interface.Invalid("{} does not define method {}".format(candidate, method.name))

    # Make sure the methods have the correct signature (to the extent possible)
    for method in iface.getProvidedMethods():
        candidate_method = getattr(candidate, method.name)
        if candidate_method.__code__ != method.func_code:
            raise zope.interface.Invalid("{} does not have the correct signature for method {}".format(candidate, method.name))

    # Make sure the candidate defines all the necessary attributes
    for attribute in iface.getProvidedAttributes():
        if not hasattr(candidate, attribute.name):
            raise zope.interface.Invalid("{} does not define attribute {}".format(candidate, attribute.name))

    # If everything checks out, return True
    return True

