    if not hasattr(candidate, "__dict__"):
        raise zope.interface.Invalid(
            f"Candidate does not define any methods: {candidate}."
        )

    # Make sure the methods have the correct signature (to the extent possible)
    for method_name, method in candidate.__dict__.items():
        # Check if method is implemented on candidate
        if not hasattr(method, "__code__"):
            continue

        # Check method signature
        method_sig = inspect.signature(method)
        iface_sig = inspect.signature(getattr(iface, method_name))
        if iface_sig != method_sig:
            raise zope.interface.Invalid(
                f"Method '{method_name}' has an incorrect signature:\n"
                f"Actual signature: '{method_sig}'.\n"
                f"Expected signature: '{iface_sig}'"
            )

    # Make sure the candidate defines all the necessary attributes
    for attr_name in iface.__slots__:
        if not hasattr(candidate, attr_name):
            raise zope.interface.Invalid(
                f"Candidate does not define attribute {attr_name}:\n"
                f"{attr_name} is required by interface {iface.__name__}."
