def process_text_links(text):

    # Split the text into individual links
    links = text.split("https://")

    # Iterate over each link and add "https://" prefix if not present
    for link in links:
        if not link.startswith("http://") and not link.startswith("https://"):
            link = "http://" + link

    # Add target="_blank" attribute to each link
    for link in links:
        link = link + ' target="_blank"'

    # Linkify each link
    for link in links:
        link = f"<a href=\"{link}\">{link}</a>"

    # Join the links back into the text
    return " ".join(links)

