def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        response = requests.head(url)
        if response.headers["Content-Type"]:
            return response.headers["Content-Type"]
        else:
            return None
    except requests.exceptions.RequestException:
        # handle any exception thrown by requests here
        pass
    except LookupError:
        # handle any LookupError thrown by requests here
        pass
    return None

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """

    try:
        # Send a HEAD request to the URL
        response = requests.head(url)

        # Check if the request was successful
        if response.status_code == 200:
            # Get the Content-Type header from the response
            content_type = response.headers.get("Content-Type")

            # Return the content type if it is not None
            if content_type is not None:
                return content_type
            else:
                return None
        else:
            # Raise an exception if the status code is not 200
            raise RuntimeError(f"Failed to fetch the content type of '{url}': {response.status_code}")
    except requests.exceptions.RequestException as e:
        # Raise an exception if the request fails
        raise RuntimeError(f"Failed to fetch the content type of '{url}': {e}")

