def dict_insert(dic, val, key, *keys):
    if not isinstance(dic, dict):
        raise ValueError("dic must be a dictionary object")
    if not isinstance(key, str):
        raise ValueError("key must be a string")
    if not isinstance(val, (str, int, float, bool)):
        raise ValueError("val must be a string, int, float, or bool")

    current_dict = dic
    for i, k in enumerate(keys):
        if not isinstance(k, str):
            raise ValueError("all keys in keys must be strings")

        if k not in current_dict:
            current_dict[k] = {}
        elif not isinstance(current_dict[k], dict):
            raise ValueError(f"key {k} already exists but its value is not a dictionary")

        current_dict = current_dict[k]

    current_dict[key] = val

    return dic

def dict_insert(dic, val, key, *keys):
    if not isinstance(dic, dict):
        raise TypeError("'dic' must be of type dict")
    if not isinstance(val, (int, float, str, bool)):
        raise TypeError("'val' must be of type (int, float, str, bool)")
    if not isinstance(key, str):
        raise TypeError("'key' must be of type str")
    if keys is not None and not all(isinstance(k, str) for k in keys):
        raise TypeError("'keys' must be of type str")

    if keys is None:
        # insert the value to the top-level key
        dic[key] = val
        return

    # recursive insertion
    current_key = key.split('.')[0]
    remaining_keys = '.'.join(key.split('.')[1:])
    if current_key not in dic:
        dic[current_key] = {}
    dict_insert(dic[current_key], val, remaining_keys, *keys)

