        raise IRValidatorException("Spec is missing mandatory metadata")

    # Check if mandatory fields are present in the spec
    if "spec" not in spec or "config" not in spec["spec"] or "template" not in spec["spec"]["config"]:
        raise IRValidatorException("Spec is missing mandatory spec/config/template fields")

    # Check if the template is a dictionary
    if not isinstance(spec["spec"]["config"]["template"], dict):
        raise IRValidatorException("Template must be a dictionary")

    # Check if the template has mandatory fields
    if "parameters" not in spec["spec"]["config"]["template"]:
        raise IRValidatorException("Template is missing mandatory parameters field")

    # If we get to this point, the spec is valid
    return spec

