def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    Parameters:
        parser_dict (dict): The dictionary to be parsed.

    Returns:
        dict: The modified dict with the included files.

    Raises:
        ValueError: If any of the files to be included are invalid or not found.

    Examples:
        >>> parser_dict = {'include_dict': {'file1.yml': ['key1', 'key2'], 'file2.yml': ['key3', 'key4']}}
        >>> _include_groups(parser_dict)
        {'file1.yml': {'key1': value1, 'key2': value2}, 'file2.yml': {'key3': value3, 'key4': value4}}
    """
    included_files = {}
    for file_path, keys in parser_dict['include_dict'].items():
        try:
            with open(file_path, 'r') as f:
                included_file = yaml.load(f, Loader=yaml.FullLoader)
                for key in keys:
                    included_files[key] = included_file[key]
        except FileNotFoundError:
            raise ValueError(f'File {file_path} not found.')
        except KeyError:
            raise ValueError(f'Key {key} not found in {file_path}.')
    return included_files

def _include_groups(self, parser_dict):
    include_groups = parser_dict.get('include-groups')
    if include_groups is None:
        raise ValueError('include-groups key is missing from the parser dictionary.')
    if not isinstance(include_groups, list):
        raise TypeError('include-groups key must be a list in the parser dictionary.')
    for group in include_groups:
        if not isinstance(group, str):
            raise TypeError('include-groups list must contain only strings.')
        if group not in self.groups:
            raise ValueError(f'Unknown group {group} in include-groups list.')
    return [include_groups]

