    for arg in self.args:
        # Check if the argument's value is specified in the spec
        if arg in self.spec:
            args[arg] = self.spec[arg]
        # Check if the argument's value is specified in the parent's argument
        elif arg in self.parent_argument.args:
            args[arg] = self.parent_argument.args[arg]
        # Check if the argument's value is specified in the environment
        elif arg in os.environ:
            args[arg] = os.environ[arg]
        # If no value is specified, use the default value
        elif hasattr(self, "default"):
            args[arg] = self.default
        else:
            raise ValueError("Could not resolve argument value")
    return args

