    def from_spec(cls, subcommand, type_name, option_name, spec_option):
        """Build the complex argument type from the specifications

        :param subcommand: the command name
        :param type_name: the complex type name
        :param option_name: the option name
        :param spec_option: option's specifications
        :return: the complex type instance
        """
        if spec_option is None:
            raise ValueError('spec_option cannot be None')

        try:
            return cls(subcommand, type_name, option_name, spec_option)
        except TypeError as e:
            raise ValueError('invalid option specification: {}'.format(e))

