class AnsiblePlaybook:
    def __init__(self, ir_workspace, ir_plugin, playbook_path, verbose=None,
                 extra_vars=None, ansible_args=None):
        self.ir_workspace = ir_workspace
        self.ir_plugin = ir_plugin
        self.playbook_path = playbook_path
        self.verbose = verbose
        self.extra_vars = extra_vars
        self.ansible_args = ansible_args

    def run(self):
        try:
            # Check if the playbook exists
            if not self.playbook_path:
                raise Exception("The playbook path is None")
            if not os.path.exists(self.playbook_path):
                raise Exception("The playbook does not exist")

            # Get the Ansible command prefix
            ansible_cmd = self.ir_plugin.get_command("ansible-playbook")
            if not ansible_cmd:
                raise Exception("The 'ansible-playbook' command is not available")

            # Set the working directory
            working_dir = os.path.dirname(self.playbook_path)
            if not working_dir:
                raise Exception("The playbook does not have a valid working directory")

            # Build the command arguments
            args = [ansible_cmd, self.playbook_path]
            if self.verbose is not None:
                args.extend(["-" + str(self.verbose)])
            if self.extra_vars:
                for key, value in self.extra_vars.items():
                    args.extend(["-e", "{}={}".format(key, json.dumps(value))])
            if self.ansible_args:
                args.extend(self.ansible_args)

            # Run the command
            proc = subprocess.Popen(args, cwd=working_dir)
            return proc.wait()
        except Exception as e:
            raise e

