import os

class AnsibleConfig:
    def __init__(self, cli_args, config_file, plugin):
        self.cli_args = cli_args
        self.config_file = config_file
        self.plugin = plugin

    def _format_extra_vars(self, extra_vars):
        count = 0
        formatted_extra_vars = ''
        for key, value in extra_vars.items():
            count += 1
            formatted_extra_vars += f'{key}=' + str(value)
            if count != len(extra_vars):
                formatted_extra_vars += ','
        return formatted_extra_vars

    def run(self, extra_vars):
        ansible_cli_args = self.cli_args + ['-i', self.config_file]
        ansible_cli_args += self._format_extra_vars(extra_vars)
        ansible_cli_args = ' '.join(ansible_cli_args)
        result = check_output(ansible_cli_args, shell=True).decode()
        return result

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    # Check if the vars_dict is not of type dict
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be of type dict")

    # Check if the cli_args is not a list
    if not isinstance(cli_args, list):
        raise ValueError("cli_args must be a list")

    # Check if the ir_workspace is not an Infrared Workspace object
    if not isinstance(ir_workspace, workspace.Workspace):
        raise ValueError("ir_workspace must be an Infrared Workspace object")

    # Check if the ir_plugin is not an InfraredPlugin object
    if not isinstance(ir_plugin, plugins.Plugin):
        raise ValueError("ir_plugin must be an InfraredPlugin object")

    # Run the Ansible playbook with the given vars_dict and cli_args
    ansible_process = subprocess.run(cli_args, capture_output=True, text=True)

    # Check if the Ansible process failed
    if ansible_process.returncode != 0:
        raise RuntimeError(f"Ansible process failed with error: {ansible_process.stderr}")

    # Return the Ansible output as a list of strings
    return ansible_process.stdout.splitlines()

