def get_plugin_spec_flatten_dict(plugin_dir: str) -> dict:
    """
    Returns a flatten dictionary containing the plugin's properties.

    :param plugin_dir: The directory path of the plugin
    :return: A flattened dictionary containing the plugin's properties
    """
    # Initialize an empty dictionary to store the flattened properties
    flatten_dict = {}

    # Get the plugin's directory content
    dir_content = os.listdir(plugin_dir)

    # Iterate through the directory content and extract the plugin's properties
    for file_name in dir_content:
        file_path = os.path.join(plugin_dir, file_name)
        if os.path.isfile(file_path):
            # Read the file's contents
            with open(file_path, "r") as f:
                file_contents = f.read()

            # Extract the plugin's properties from the file's contents
            if file_name.endswith(".json"):
                try:
                    properties = json.loads(file_contents)
                    flatten_dict.update(properties)
                except json.JSONDecodeError:
                    raise ValueError(f"Invalid JSON file: {file_name}")
            elif file_name.endswith(".yml"):
                try:
                    properties = yaml.safe_load(file_contents)
                    flatten_dict.update(properties)
                except yaml.YAMLError:
                    raise ValueError(f"Invalid YAML file: {file_name}")

    return flatten_dict

